// Package report builds a human-readable security briefing from the alert
// history. It is intentionally dependency-free (standard library only) so it
// can be generated by the dashboard without adding a scheduler library.
//
// 設計方針:
//   - 数値の羅列ではなく「読み物」としてまとめる（攻撃傾向・注目アラート・
//     改善提案）。
//   - 機密はマスキングする: IP アドレスは件数のみ、ユーザー名はそのまま出すが
//     外部共有を想定しない（本文は admin 向け）。
//   - 出力は Markdown（Email 本文・ファイル保存の両方に使える）。
package report

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"Kizuna-Eye/pkg/alert"
)

// Options controls report generation.
type Options struct {
	// Title overrides the report heading (default: "Kizuna-Eye 週次セキュリティレポート").
	Title string
	// Language is "ja" or "en" (default ja).
	Language string
	// Period is the reporting window ending at Now.
	Period time.Duration
	// Now is the report time (default time.Now()).
	Now time.Time
	// MaxItems caps the number of alerts listed in the highlights section.
	MaxItems int
	// Score, when non-nil, is included as the current security score.
	Score *int
}

// Result is the generated report.
type Result struct {
	Subject  string
	Markdown string
	Total    int
	Critical int
	Warning  int
}

// Generate builds a Markdown briefing from the alert history entries.
// Entries are expected newest-first (as returned by alert.History.List).
func Generate(entries []alert.HistoryEntry, opts Options) Result {
	now := opts.Now
	if now.IsZero() {
		now = time.Now()
	}
	period := opts.Period
	if period <= 0 {
		period = 7 * 24 * time.Hour
	}
	maxItems := opts.MaxItems
	if maxItems <= 0 {
		maxItems = 20
	}
	title := opts.Title
	if title == "" {
		title = "Kizuna-Eye 週次セキュリティレポート"
	}

	// Filter to the reporting window.
	since := now.Add(-period)
	var inWindow []alert.HistoryEntry
	for _, e := range entries {
		if e.Timestamp.IsZero() || e.Timestamp.Before(since) {
			continue
		}
		inWindow = append(inWindow, e)
	}

	// Aggregate.
	levelCount := map[string]int{}
	typeCount := map[string]int{}
	var critical []alert.HistoryEntry
	for _, e := range inWindow {
		levelCount[strings.ToLower(e.Level)]++
		if e.Type != "" {
			typeCount[e.Type]++
		}
		if strings.EqualFold(e.Level, "critical") {
			critical = append(critical, e)
		}
	}

	res := Result{
		Total:    len(inWindow),
		Critical: levelCount["critical"],
		Warning:  levelCount["warning"],
	}

	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\n", title)
	fmt.Fprintf(&b, "- 対象期間: %s 〜 %s\n", since.Format("2006-01-02 15:04"), now.Format("2006-01-02 15:04"))
	fmt.Fprintf(&b, "- 総アラート数: **%d**（critical %d / warning %d）\n", res.Total, res.Critical, res.Warning)
	if opts.Score != nil {
		fmt.Fprintf(&b, "- セキュリティスコア: **%d / 100**\n", *opts.Score)
	}
	b.WriteString("\n")

	// Summary.
	b.WriteString("## 概要\n\n")
	if res.Total == 0 {
		b.WriteString("この期間にアラートはありませんでした。\n\n")
	} else {
		fmt.Fprintf(&b, "この期間に %d 件のアラートを検知しました。うち重大（critical）が %d 件です。\n\n", res.Total, res.Critical)
	}

	// Trending types.
	if len(typeCount) > 0 {
		b.WriteString("## 検知種別（多い順）\n\n")
		for _, kv := range topN(typeCount, 10) {
			// sanitizeLine, not the raw key: the alert Type is derived from
			// agent/plugin-reported data ("security_" + category), so an
			// attacker who can emit a security event controls it. A newline
			// in the key would otherwise inject an extra Markdown bullet or
			// even a heading into the report (title/message are already
			// sanitized above; the key was the one field that was not).
			fmt.Fprintf(&b, "- %s: %d 件\n", sanitizeLine(kv.key), kv.n)
		}
		b.WriteString("\n")
	}

	// Critical highlights.
	if len(critical) > 0 {
		b.WriteString("## 注目すべき重大アラート\n\n")
		n := len(critical)
		if n > maxItems {
			n = maxItems
		}
		for i := 0; i < n; i++ {
			e := critical[i]
			fmt.Fprintf(&b, "- [%s] %s\n", e.Timestamp.Format("01-02 15:04"), sanitizeLine(e.Title))
			if e.Message != "" {
				fmt.Fprintf(&b, "  - %s\n", sanitizeLine(e.Message))
			}
		}
		if len(critical) > n {
			fmt.Fprintf(&b, "- … 他 %d 件\n", len(critical)-n)
		}
		b.WriteString("\n")
	}

	// Recommendations.
	b.WriteString("## 改善提案\n\n")
	for _, rec := range recommendations(inWindow) {
		fmt.Fprintf(&b, "- %s\n", rec)
	}
	b.WriteString("\n")

	b.WriteString("---\n")
	fmt.Fprintf(&b, "_このレポートは Kizuna-Eye が自動生成しました（%s）。_\n", now.Format(time.RFC3339))

	res.Markdown = b.String()
	res.Subject = fmt.Sprintf("[Kizuna-Eye] 週次セキュリティレポート (%s)", now.Format("2006-01-02"))
	return res
}

// recommendations derives a few concrete improvement hints from the window.
func recommendations(entries []alert.HistoryEntry) []string {
	var recs []string
	ssh := 0
	integrity := 0
	suid := 0
	port := 0
	cron := 0
	for _, e := range entries {
		switch {
		case strings.Contains(e.Type, "ssh"):
			ssh++
		case strings.Contains(e.Type, "integrity"):
			integrity++
		case strings.Contains(e.Type, "suid"):
			suid++
		case strings.Contains(e.Type, "listen_port"):
			port++
		case strings.Contains(e.Type, "cron"):
			cron++
		}
	}
	if ssh >= 5 {
		recs = append(recs, "SSH ログイン失敗が多い。`block_mode=enforce` の有効化、鍵認証への一本化、Fail2ban 相当の自動ブロックを検討する。")
	}
	if integrity > 0 {
		recs = append(recs, "ファイル改ざん検知あり。`integrity_files` の対象見直しと、ベースラインの再取得を検討する。")
	}
	if suid > 0 {
		recs = append(recs, "SUID/SGID の出現あり。不要な SUID ビットの削除と、監視パスの絞り込みを検討する。")
	}
	if port > 0 {
		recs = append(recs, "新規リッスンポートあり。意図したサービスか確認し、不要なら停止する。")
	}
	if cron > 0 {
		recs = append(recs, "cron 変更あり。永続化の試みか確認し、不要なジョブを削除する。")
	}
	if len(recs) == 0 {
		recs = append(recs, "この期間は目立った兆候なし。定期レポートとセキュリティスコアの確認を継続する。")
	}
	return recs
}

// sanitizeLine collapses newlines so a log-derived value cannot inject extra
// Markdown structure into the report.
func sanitizeLine(s string) string {
	s = strings.ReplaceAll(s, "\r", " ")
	s = strings.ReplaceAll(s, "\n", " ")
	if len([]rune(s)) > 200 {
		r := []rune(s)
		s = string(r[:200]) + "…"
	}
	return s
}

type kv struct {
	key string
	n   int
}

func topN(m map[string]int, n int) []kv {
	out := make([]kv, 0, len(m))
	for k, v := range m {
		out = append(out, kv{key: k, n: v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].n != out[j].n {
			return out[i].n > out[j].n
		}
		return out[i].key < out[j].key
	})
	if len(out) > n {
		out = out[:n]
	}
	return out
}
